def test_hyb_gga_xc_whpbe0_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_whpbe0", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.111875773363452e+00, -1.090404580910927e+00, -1.060311929794400e+00, -1.018614517621044e+00, -9.617770886776050e-01, -8.861050976934389e-01, -7.886991080328799e-01, -6.692274056047456e-01, -5.324624322251820e-01, -3.897204905975118e-01, -2.547151451091110e-01, -1.877887970882336e-01, -1.697299630157604e-01, -1.301721559161256e-01, -8.156634544323574e-02, -3.839273475852461e-02, -1.112377711733587e-02, -4.981079251882700e-04, -2.716387804209288e-06, -3.725787025160893e-09]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


